insert into public.posts (id, frente, areas, autor, data, fotos, seed, titulo, resumo, corpo) values
  ('cristais-coloridos', 'experimenta', array['C', 'R', 'A2']::text[], 'equipe', '2026-10-14', 6, 401, 'Cristais azuis e vermelhos: estudantes cultivam os próprios cristais no ICT', 'No laboratório, cada estudante preparou a solução, colocou o fio-semente e acompanhou o cristal crescer dia após dia.', '[{"p":"Nesta edição do Cristhaal Experimenta, os estudantes entraram no laboratório da Unifesp em São José dos Campos para viver um experimento de cristalização do começo ao fim."},{"p":"O processo seguiu quatro etapas:"},{"steps":true},{"p":"O resultado foram cristais azuis, vermelhos e de outras cores, cada um com um formato diferente. Mais do que o cristal em si, o que ficou foi a emoção de ver a ciência acontecer com as próprias mãos."}]'::jsonb),
  ('decolar-no-ict', 'educa', array['C', 'R', 'S', 'I']::text[], 'coord', '2026-10-02', 8, 517, 'Programa Decolar no ICT: um dia dentro dos laboratórios', 'Estudantes do Programa Decolar conheceram laboratórios de pesquisa e participaram de seminários de matemática, física, química e biologia.', '[{"p":"Recebemos estudantes do Programa Decolar para um dia inteiro no Instituto de Ciência e Tecnologia. A programação incluiu visitas a laboratórios e seminários pensados especialmente para eles."},{"p":"Ao longo do dia, os estudantes conversaram com pesquisadores e fizeram perguntas que surpreenderam muita gente da casa. A ideia é que eles enxerguem a universidade como um lugar possível para o futuro deles."}]'::jsonb),
  ('sonia-guimaraes', 'inspira', array['C', 'H', 'S']::text[], 'equipe', '2026-09-25', 2, 263, 'Sonia Guimarães e a física feita aqui do lado', 'Primeira mulher negra brasileira doutora em física e professora do ITA, em São José dos Campos.', '[{"p":"Abrimos a série do Cristhaal Inspira com uma cientista que trabalha bem perto de nós. Sonia Guimarães é a primeira mulher negra brasileira com doutorado em física e é professora do ITA, aqui em São José dos Campos."},{"p":"Contar a trajetória dela para os estudantes é mostrar que a ciência também tem rostos parecidos com os deles. Representatividade importa."}]'::jsonb),
  ('cristais-no-cotidiano', 'educa', array['C', 'T', 'L']::text[], 'equipe', '2026-09-18', 4, 88, 'Do sal de cozinha ao chip do celular: tem cristal em tudo', 'Uma aula numa escola pública da região sobre os cristais escondidos no dia a dia.', '[{"p":"Levamos lupas, amostras e muitas perguntas para uma turma de escola pública da região. O desafio era encontrar cristais em objetos comuns."},{"p":"Sal, açúcar, gelo, a tela e o processador do celular: no fim da aula, a turma já estava vendo cristal em todo canto."}]'::jsonb),
  ('enedina-alves-marques', 'inspira', array['T', 'H', 'S']::text[], 'equipe', '2026-09-11', 3, 331, 'Enedina Alves Marques, a primeira engenheira negra do Brasil', 'Formada em engenharia civil no Paraná em 1945, abriu caminho para muitas outras.', '[{"p":"Enedina Alves Marques se formou em engenharia civil no Paraná, em 1945, e se tornou a primeira mulher negra engenheira do país."},{"p":"Neste post, a equipe conta como foi a conversa com os estudantes sobre a trajetória dela e sobre o que ainda falta para a engenharia ser um lugar de todas e todos."}]'::jsonb),
  ('prazer-cristhaal', 'geral', array['R', 'I', 'A1', 'A2', 'L']::text[], 'coord', '2026-09-04', 5, 742, 'Prazer, Cristhaal: de uma conversa entre professoras a um projeto', 'Como três professoras de áreas diferentes transformaram uma conversa sobre cristais num projeto de extensão.', '[{"p":"O Cristhaal nasceu de uma conversa descontraída entre três professoras de áreas totalmente diferentes. O assunto era a presença dos cristais no cotidiano, enorme e quase invisível."},{"p":"Daí surgiu a vontade de mostrar a importância dos cristais na ciência, na tecnologia, na matemática, na história, na filosofia, na arquitetura e na arte. Vamos explorar o lado lúdico dos cristais além da sua forma visível."}]'::jsonb)
